# -*- coding: utf-8 -*-
"""生成 `market_state_golden_test.go`：用**原版模块本身**算出市场状态的黄金值。

与量价特征那套同理：`build_market_width_daily` 的分组/均值口径、
`_detect_market_state_from_prepared_width` 的窗口切法与打分阈值、
`build_market_state_cache` 的 `searchsorted(side="right")` 边界，
全是容易"看起来对、数值不同"的地方。这里直接 import 原模块跑出结果再逐项比对。

用法：

    python internal/volprice/testdata/gen_market_state_golden.py \
        --original "D:\\workspace\\python\\stock\\tushare-stock-tonyz\\pythonProject\\pythonProject" \
        --out internal/volprice/market_state_golden_test.go
"""

from __future__ import annotations

import argparse
import json
import math
import os
import shutil
import subprocess
import sys


def go_str(value) -> str:
    return json.dumps(str(value), ensure_ascii=False)


def go_float(value) -> str:
    if value is None:
        return "nan()"
    f = float(value)
    if math.isnan(f):
        return "nan()"
    if math.isinf(f):
        return "math.Inf(1)" if f > 0 else "math.Inf(-1)"
    return repr(f)


def market_rows(pd):
    """确定性"全市场日线"：3 只股票 × 60 个交易日，故意掺一点缺失值。"""
    rows = []
    for day in range(60):
        date = f"2026{(day // 28) + 1:02d}{(day % 28) + 1:02d}"
        for stock in range(3):
            close = 10.0 + stock + day * (0.05 + stock * 0.02) + ((day + stock) % 5) * 0.1
            pre_close = close / (1.0 + (((day + stock) % 7) - 3) / 100.0)
            pct = (close / pre_close - 1.0) * 100.0
            row = {
                "trade_date": date,
                "close": close,
                "pre_close": pre_close,
                "pct_chg": pct,
                "amount": 1_000_000.0 + day * 1000.0 + stock * 500.0,
            }
            # 制造缺失：第 10 天第 0 只用 NaN 的 pct_chg（走 close/pre_close 分支）
            if day == 10 and stock == 0:
                row["pct_chg"] = None
            rows.append(row)
    return pd.DataFrame(rows)


def stock_bars(pd):
    """单只股票的 K 线（给 detect_stock_context_state_prepared 用）。"""
    rows = []
    for day in range(70):
        base = 20.0 + day * 0.08 + (day % 6) * 0.25
        rows.append(
            {
                "trade_date": f"2026{(day // 28) + 1:02d}{(day % 28) + 1:02d}",
                "open": base - 0.1,
                "high": base + 0.3,
                "low": base - 0.2,
                "close": base,
                "volume": 500_000.0 + day * 1000.0,
            }
        )
    return pd.DataFrame(rows)


STATE_FIELDS = ("state", "label", "score", "source", "reason", "trade_date")


def emit_state_map(lines, name, mapping, keys):
    lines.append("var %s = map[string]goldenState{" % name)
    for key in keys:
        info = mapping.get(key) or {}
        lines.append(
            "\t%s: {%s, %s, %s, %s, %s, %s},"
            % (
                go_str(key),
                go_str(info.get("state", "")),
                go_str(info.get("label", "")),
                go_float(info.get("score", 0.0)),
                go_str(info.get("source", "")),
                go_str(info.get("reason", "")),
                go_str(info.get("trade_date", "")),
            )
        )
    lines.append("}")
    lines.append("")


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--original", required=True)
    parser.add_argument("--out", required=True)
    args = parser.parse_args()

    if args.original not in sys.path:
        sys.path.insert(0, args.original)

    import pandas as pd  # noqa: E402
    import volume_price_market_state as vpms  # noqa: E402

    frame = market_rows(pd)
    width = vpms.build_market_width_daily(frame)
    dates = [str(x) for x in width["trade_date"].tolist()]
    probe_dates = [dates[0], dates[19], dates[39], dates[-1]]
    cache_dates = [dates[5], dates[19], dates[-1]]

    lines = []
    lines.append("// Code generated by testdata/gen_market_state_golden.py; DO NOT EDIT.")
    lines.append("//")
    lines.append("// 黄金值由**原版 volume_price_market_state** 在同一份输入上跑出。")
    lines.append("package volprice")
    lines.append("")
    import_index = len(lines)

    lines.append("type goldenMarketRow struct {")
    lines.append("\tTradeDate string")
    lines.append("\tClose float64")
    lines.append("\tPreClose float64")
    lines.append("\tPctChg float64")
    lines.append("\tAmount float64")
    lines.append("}")
    lines.append("")
    lines.append("// 原帧：pct_chg 列存在但**有 NaN 单元格**（不全为 NaN）")
    lines.append("const goldenHasPctChgColumn = true")
    lines.append("const goldenHasAmountColumn = true")
    lines.append("")
    lines.append("var goldenMarketRows = []goldenMarketRow{")
    for _, row in frame.iterrows():
        pct = row["pct_chg"]
        lines.append(
            "\t{%s, %s, %s, %s, %s},"
            % (
                go_str(row["trade_date"]),
                go_float(row["close"]),
                go_float(row["pre_close"]),
                go_float(pct),
                go_float(row["amount"]),
            )
        )
    lines.append("}")
    lines.append("")

    # 第二组：**整列缺失** → 走 close/pre_close 补算分支
    derived = frame.drop(columns=["pct_chg"])
    derived_width = vpms.build_market_width_daily(derived)
    lines.append("// 派生帧：完全没有 pct_chg 列 → 走 close/pre_close 补算分支")
    lines.append("const goldenDeriveHasPctChgColumn = false")
    lines.append("var goldenDeriveRows = []goldenMarketRow{")
    for _, row in derived.iterrows():
        lines.append(
            "\t{%s, %s, %s, nan(), %s},"
            % (
                go_str(row["trade_date"]),
                go_float(row["close"]),
                go_float(row["pre_close"]),
                go_float(row["amount"]),
            )
        )
    lines.append("}")
    lines.append("")
    lines.append("var goldenDeriveWidth = []WidthDaily{")
    for _, row in derived_width.iterrows():
        lines.append(
            "\t{%s, %s, %s, %s, %s, %s},"
            % (
                go_str(row["trade_date"]),
                go_float(row["avg_pct"]),
                go_float(row["up_ratio"]),
                go_float(row["down_ratio"]),
                go_float(row["amount"]),
                go_float(row["count"]),
            )
        )
    lines.append("}")
    lines.append("")

    lines.append("var goldenWidth = []WidthDaily{")
    for _, row in width.iterrows():
        lines.append(
            "\t{%s, %s, %s, %s, %s, %s},"
            % (
                go_str(row["trade_date"]),
                go_float(row["avg_pct"]),
                go_float(row["up_ratio"]),
                go_float(row["down_ratio"]),
                go_float(row["amount"]),
                go_float(row["count"]),
            )
        )
    lines.append("}")
    lines.append("")

    lines.append("type goldenState struct {")
    lines.append("\tState string")
    lines.append("\tLabel string")
    lines.append("\tScore float64")
    lines.append("\tSource string")
    lines.append("\tReason string")
    lines.append("\tTradeDate string")
    lines.append("}")
    lines.append("")

    from_width = {d: vpms.detect_market_state_from_width(width, current_date=d) for d in probe_dates}
    emit_state_map(lines, "goldenFromWidth", from_width, probe_dates)

    cache = vpms.build_market_state_cache(frame, cache_dates)
    emit_state_map(lines, "goldenCache", cache, cache_dates)

    bars = stock_bars(pd)
    bars_dates = [str(x) for x in bars["trade_date"].tolist()]
    bars_probe = [bars_dates[0], bars_dates[19], bars_dates[-1]]
    stock_states = {
        d: vpms.detect_stock_context_state_prepared(bars, current_date=d) for d in bars_probe
    }
    emit_state_map(lines, "goldenStockState", stock_states, bars_probe)

    lines.append("var goldenStockBars = []goldenBar{")
    for _, row in bars.iterrows():
        lines.append(
            "\t{%s, %s, %s, %s, %s, %s},"
            % (
                go_str(row["trade_date"]),
                go_float(row["open"]),
                go_float(row["high"]),
                go_float(row["low"]),
                go_float(row["close"]),
                go_float(row["volume"]),
            )
        )
    lines.append("}")
    lines.append("")

    if "math.Inf" in "\n".join(lines):
        lines[import_index:import_index] = ["import \"math\"", ""]

    os.makedirs(os.path.dirname(os.path.abspath(args.out)), exist_ok=True)
    with open(args.out, "w", encoding="utf-8", newline="\n") as handle:
        handle.write("\n".join(lines))
    gofmt = shutil.which("gofmt")
    if gofmt:
        subprocess.run([gofmt, "-w", args.out], check=True)
    print(f"wrote {args.out}: width={len(width)} rows, probes={len(probe_dates)}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
